        const std::size_t aIndexD = (1U * W_KEY) + ((aIndex + 1870U) & W_KEY1);

        std::uint32_t aFoldValue = 0U;
        aFoldValue |= static_cast<std::uint32_t>(aSourceLaneA[aIndexA]) << 0U;
        aFoldValue |= static_cast<std::uint32_t>(aSourceLaneB[aIndexB]) << 16U;
